using Microsoft.EntityFrameworkCore;
using System.Text.Json;
namespace Society.Api;

public static class OrganizationEndpoints
{
    static readonly string[] Statuses = ["Proposed", "Pending Approval", "Active", "Suspended", "Inactive", "Closed", "Merged", "Archived"];
    public static void Map(RouteGroupBuilder api)
    {
        var t = api.MapGroup("/societies/{tenant:guid}").RequireAuthorization();
        t.MapGet("/organizations/levels", async (Guid tenant, AppDb db, Access a) => { await a.Member(tenant); return await db.Levels.Where(x => x.TenantId == tenant).OrderBy(x => x.Name).Select(x => new { x.Id, x.Name, x.Kind, x.AllowedParents, x.AllowRoot }).ToListAsync(); });
        t.MapPost("/organizations/levels", async (Guid tenant, LevelRequest r, AppDb db, Access a) => { await a.Require(tenant, "hierarchy.manage"); if (string.IsNullOrWhiteSpace(r.Name) || r.Name.Length > 80 || !new[] { "Other", "Region", "Chapter" }.Contains(r.Kind) || await db.Levels.CountAsync(x => x.TenantId == tenant && r.AllowedParents.Contains(x.Id)) != r.AllowedParents.Distinct().Count()) throw new DomainException("Invalid level or parent types"); var level = new Level { TenantId = tenant, Name = r.Name.Trim(), Kind = r.Kind, AllowedParents = r.AllowedParents, AllowRoot = r.AllowRoot }; db.Levels.Add(level); a.Audit(tenant, "level.created", level.Id); await db.SaveChangesAsync(); return Results.Ok(new { level.Id }); });
        t.MapPut("/organizations/levels/{id:guid}", async (Guid tenant, Guid id, LevelRequest r, AppDb db, Access a) => { await a.Require(tenant, "hierarchy.manage"); await using var tx = await db.Database.BeginTransactionAsync(); await Lock(tenant, db); var l = await db.Levels.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id); if (l == null) return Results.NotFound(); if (string.IsNullOrWhiteSpace(r.Name) || r.Name.Length > 80 || !new[] { "Other", "Region", "Chapter" }.Contains(r.Kind) || await db.Levels.CountAsync(x => x.TenantId == tenant && r.AllowedParents.Contains(x.Id)) != r.AllowedParents.Distinct().Count()) throw new DomainException("Invalid level definition"); if (await db.Units.AnyAsync(u => u.TenantId == tenant && u.LevelId == id && ((u.ParentId == null && !r.AllowRoot) || (u.ParentId != null && !db.Units.Any(p => p.Id == u.ParentId && r.AllowedParents.Contains(p.LevelId)))))) throw new DomainException("Existing units would violate the new parent rules"); l.Name = r.Name.Trim(); l.Kind = r.Kind; l.AllowedParents = r.AllowedParents; l.AllowRoot = r.AllowRoot; a.Audit(tenant, "level.updated", id, r); await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.NoContent(); });
        t.MapGet("/organizations/units", async (Guid tenant, Guid? parentId, Guid? workspace, string? kind, string? search, string? status, string? sort, bool? descending, int? page, int? pageSize, AppDb db, Access a) => { await a.Member(tenant); var q = a.InWorkspace(a.Visible(tenant), tenant, workspace); if (parentId != null) q = q.Where(x => x.ParentId == parentId); if (kind == "roots") { var visible = q; q = q.Where(x => x.ParentId == null || !visible.Any(p => p.Id == x.ParentId)); } else if (!string.IsNullOrEmpty(kind)) q = q.Where(x => db.Levels.Any(l => l.Id == x.LevelId && l.Kind == kind)); if (!string.IsNullOrWhiteSpace(search)) { var term = search.ToLower(); q = q.Where(x => x.Name.ToLower().Contains(term) || x.Code.ToLower().Contains(term)); } if (!string.IsNullOrEmpty(status)) q = q.Where(x => x.Status == status); var size = Math.Clamp(pageSize ?? 20, 1, 100); var total = await q.CountAsync(); var ordered = sort == "code" ? (descending == true ? q.OrderByDescending(x => x.Code) : q.OrderBy(x => x.Code)) : sort == "status" ? (descending == true ? q.OrderByDescending(x => x.Status) : q.OrderBy(x => x.Status)) : (descending == true ? q.OrderByDescending(x => x.Name) : q.OrderBy(x => x.Name)); var items = await ordered.ThenBy(x => x.Id).Skip(Math.Max(0, (page ?? 1) - 1) * size).Take(size).Select(x => new { x.Id, x.Name, x.Code, x.ParentId, x.LevelId, x.Status, x.Details, x.Revision, chapters = AppDb.ChapterCount(tenant, x.Id), head = (from ass in db.Assignments join role in db.GovernanceRoles on ass.RoleId equals role.Id join user in db.Users on ass.UserId equals user.Id where ass.TenantId == tenant && ass.UnitId == x.Id && ass.StartsAt <= DateTimeOffset.UtcNow && (ass.EndsAt == null || ass.EndsAt > DateTimeOffset.UtcNow) && (role.Name.Contains("President") || role.Name.Contains("Coordinator") || role.Name.Contains("Governor")) orderby ass.StartsAt descending select user.FullName).FirstOrDefault(), level = db.Levels.Where(l => l.Id == x.LevelId).Select(l => l.Name).First(), children = db.Units.Count(c => c.TenantId == tenant && c.ParentId == x.Id) }).ToListAsync(); return Results.Ok(new { items, total, page = page ?? 1, pageSize = size }); });
        t.MapGet("/organizations/units/{id:guid}", async (Guid tenant, Guid id, AppDb db, Access a) => { await a.Require(tenant, "units.read", id); return await db.Units.Where(x => x.TenantId == tenant && x.Id == id).Select(x => new { x.Id, x.Name, x.Code, x.LevelId, x.ParentId, x.Status, x.Details, x.Revision, x.CreatedAt, x.UpdatedAt }).SingleOrDefaultAsync() is { } u ? Results.Ok(u) : Results.NotFound(); });
        t.MapPost("/organizations/units", async (Guid tenant, UnitRequest r, AppDb db, Access a) => { await a.Require(tenant, "units.write", r.ParentId); await using var tx = await db.Database.BeginTransactionAsync(); await Lock(tenant, db); await Validate(tenant, null, r, db); var unit = new Unit { TenantId = tenant }; Apply(unit, r); db.Units.Add(unit); a.Audit(tenant, "unit.created", unit.Id, r); await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.Ok(new { unit.Id }); });
        t.MapPut("/organizations/units/{id:guid}", async (Guid tenant, Guid id, UnitRequest r, AppDb db, Access a) => { await a.Require(tenant, "units.write", id); await using var tx = await db.Database.BeginTransactionAsync(); await Lock(tenant, db); var unit = await db.Units.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id); if (unit == null) return Results.NotFound(); if (unit.Revision != r.Revision) return Results.Conflict(new { title = "Record changed. Refresh before editing." }); if (unit.ParentId != r.ParentId) { await a.Require(tenant, "hierarchy.manage", id); await a.Require(tenant, "units.write", r.ParentId); } await Validate(tenant, id, r, db); a.Audit(tenant, "unit.updated", id, new { before = new { unit.Name, unit.ParentId, unit.Status, unit.Details }, after = r }); Apply(unit, r); await db.SaveChangesAsync(); await tx.CommitAsync(); return Results.NoContent(); });
        t.MapGet("/role-candidates", async (Guid tenant, string? search, AppDb db, Access a) => { await a.Require(tenant, "roles.manage"); var query = from link in db.Links join user in db.Users on link.UserId equals user.Id where link.TenantId == tenant select user; if (!string.IsNullOrWhiteSpace(search)) query = query.Where(x => x.FullName.ToLower().Contains(search.ToLower())); return await query.OrderBy(x => x.FullName).Take(30).Select(x => new { x.Id, x.FullName }).ToListAsync(); });
        t.MapGet("/permissions", async (Guid tenant, Access a) => { await a.Require(tenant, "roles.manage"); return Access.Permissions; });
        t.MapGet("/roles", async (Guid tenant, AppDb db, Access a) => { await a.Require(tenant, "roles.manage"); return await db.GovernanceRoles.Where(x => x.TenantId == tenant).Select(x => new { x.Id, x.Name, x.Permissions, x.Responsibilities,managed=x.Name=="Member Directory" }).ToListAsync(); });
        t.MapPost("/roles", async (Guid tenant, RoleRequest r, AppDb db, Access a) => { await a.Require(tenant, "roles.manage"); if (string.IsNullOrWhiteSpace(r.Name) || r.Name.Length > 100 || r.Permissions.Except(Access.Permissions).Any()) throw new DomainException("Invalid role"); foreach (var p in r.Permissions) await a.Require(tenant, p); var role = new GovernanceRole { TenantId = tenant, Name = r.Name.Trim(), Permissions = r.Permissions.Distinct().ToArray(), Responsibilities = r.Responsibilities }; db.GovernanceRoles.Add(role); a.Audit(tenant, "role.created", role.Id); await db.SaveChangesAsync(); return Results.Ok(new { role.Id }); });
        t.MapPut("/roles/{id:guid}", async (Guid tenant, Guid id, RoleRequest r, AppDb db, Access a) => { await a.Require(tenant, "roles.manage"); if (string.IsNullOrWhiteSpace(r.Name) || r.Name.Length > 100 || r.Permissions.Except(Access.Permissions).Any()) throw new DomainException("Invalid role"); foreach (var permission in r.Permissions) await a.Require(tenant, permission); var role = await db.GovernanceRoles.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id); if (role == null) return Results.NotFound();if(role.Name=="Member Directory")throw new DomainException("This baseline role is managed by membership and privacy policies"); role.Name = r.Name.Trim(); role.Permissions = r.Permissions.Distinct().ToArray(); role.Responsibilities = r.Responsibilities; a.Audit(tenant, "role.updated", id, r); await db.SaveChangesAsync(); return Results.NoContent(); });
        t.MapGet("/role-assignments", async (Guid tenant, int? page, AppDb db, Access a) => { await a.Require(tenant, "roles.manage"); return await (from ass in db.Assignments join r in db.GovernanceRoles on ass.RoleId equals r.Id join u in db.Users on ass.UserId equals u.Id where ass.TenantId == tenant select new { ass.Id, ass.UserId, ass.UnitId, ass.StartsAt, ass.EndsAt, role = r.Name, user = u.FullName }).OrderBy(x => x.user).ThenBy(x => x.Id).Skip(Math.Clamp((page ?? 1) - 1, 0, 1000000) * 100).Take(100).ToListAsync(); });
        t.MapPost("/role-assignments", async (Guid tenant, AssignmentRequest r, AppDb db, Access a) => { await a.Require(tenant, "roles.manage"); var role = await db.GovernanceRoles.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == r.RoleId) ?? throw new DomainException("Role not found"); foreach (var p in role.Permissions) await a.Require(tenant, p); if (r.EndsAt <= r.StartsAt) throw new DomainException("End date must follow start date"); var assignment = new Assignment { TenantId = tenant, UserId = r.UserId, RoleId = r.RoleId, UnitId = r.UnitId, StartsAt = r.StartsAt.ToUniversalTime(), EndsAt = r.EndsAt?.ToUniversalTime() }; db.Assignments.Add(assignment); a.Audit(tenant, "role.assigned", assignment.Id); await db.SaveChangesAsync(); return Results.Ok(new { assignment.Id }); });
        t.MapDelete("/role-assignments/{id:guid}", async (Guid tenant, Guid id, AppDb db, Access a) => { await a.Require(tenant, "roles.manage"); var ass = await db.Assignments.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == id); if (ass == null) return Results.NotFound(); if (ass.UserId == a.UserId) throw new DomainException("Another society administrator must revoke your assignment"); ass.RevokedAt = DateTimeOffset.UtcNow; ass.EndsAt = ass.StartsAt >= DateTimeOffset.UtcNow ? ass.StartsAt.AddTicks(10) : DateTimeOffset.UtcNow; a.Audit(tenant, "role.revoked", id); await db.SaveChangesAsync(); return Results.NoContent(); });
    }
    static Task<int> Lock(Guid tenant, AppDb db) => db.Database.ExecuteSqlInterpolatedAsync($"SELECT pg_advisory_xact_lock(hashtext({tenant.ToString()}))");
    static void Apply(Unit u, UnitRequest r) { u.LevelId = r.LevelId; u.ParentId = r.ParentId; u.Name = r.Name.Trim(); u.Code = r.Code.Trim().ToUpperInvariant(); u.Status = r.Status; u.Details = r.Details; u.Revision++; u.UpdatedAt = DateTimeOffset.UtcNow; }
    static async Task Validate(Guid tenant, Guid? id, UnitRequest r, AppDb db) { if (!Statuses.Contains(r.Status) || r.Details.Length > 32000) throw new DomainException("Invalid status or oversized details"); try { using var doc = JsonDocument.Parse(r.Details); if (doc.RootElement.ValueKind != JsonValueKind.Object) throw new DomainException("Details must be an object"); foreach (var key in new[] { "website", "logoUrl", "coverUrl" }) if (doc.RootElement.TryGetProperty(key, out var v) && v.ValueKind == JsonValueKind.String && !string.IsNullOrWhiteSpace(v.GetString()) && !((key != "website" && v.GetString()!.StartsWith($"/api/v1/societies/{tenant}/assets/")) || (Uri.TryCreate(v.GetString(), UriKind.Absolute, out var url) && url.Scheme == "https"))) throw new DomainException("Website and image URLs must use HTTPS"); } catch (DomainException) { throw; } catch { throw new DomainException("Invalid details JSON"); } var level = await db.Levels.SingleOrDefaultAsync(x => x.TenantId == tenant && x.Id == r.LevelId) ?? throw new DomainException("Invalid organizational level"); if (r.ParentId == null) { if (!level.AllowRoot) throw new DomainException("This level requires a parent"); } else { var parent = await db.Units.SingleOrDefaultAsync(x => x.Id == r.ParentId && x.TenantId == tenant) ?? throw new DomainException("Parent not in this society"); if (!level.AllowedParents.Contains(parent.LevelId)) throw new DomainException("This parent level is not permitted"); var seen = new HashSet<Guid>(); Guid? current = parent.Id; while (current != null) { if (current == id || !seen.Add(current.Value)) throw new DomainException("Hierarchy cycle rejected"); current = await db.Units.Where(x => x.TenantId == tenant && x.Id == current).Select(x => x.ParentId).SingleAsync(); } } }
}
